 57→// stuckSession holds a session state along with diagnostic info.
 58→type stuckSession struct {
 59→	State             *strategy.SessionState
 60→	Reason            string
 61→	ShadowBranch      string
 62→	HasShadowBranch   bool
 63→	CheckpointCount   int
 64→	FilesTouchedCount int
 65→}
