 67→func runSessionsFix(cmd *cobra.Command, force bool) error {
 68→	// Check 1: Disconnected metadata branches
 69→	metadataErr := checkDisconnectedMetadata(cmd, force)
 70→	if metadataErr != nil {
 71→		fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
 72→	}
 73→	fmt.Fprintln(cmd.OutOrStdout())
 74→
 75→	// Check 2: Stuck sessions
 76→	ctx := cmd.Context()
 77→	// Load all session states
 78→	states, err := strategy.ListSessionStates(ctx)
 79→	if err != nil {
 80→		return fmt.Errorf("failed to list session states: %w", err)
 81→	}
 82→
 83→	if len(states) == 0 {
 84→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 85→		if metadataErr != nil {
 86→			return fmt.Errorf("metadata check failed: %w", metadataErr)
 87→		}
 88→		return nil
 89→	}
 90→
 91→	// Open repository to check shadow branches (uses worktree-aware helper)
 92→	repo, err := openRepository(ctx)
 93→	if err != nil {
 94→		return fmt.Errorf("failed to open repository: %w", err)
 95→	}
 96→
 97→	// Identify stuck sessions
 98→	now := time.Now()
 99→	var stuck []stuckSession
100→
101→	for _, state := range states {
102→		ss := classifySession(state, repo, now)
103→		if ss != nil {
104→			stuck = append(stuck, *ss)
105→		}
106→	}
107→
108→	if len(stuck) == 0 {
109→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
110→		if metadataErr != nil {
111→			return fmt.Errorf("metadata check failed: %w", metadataErr)
112→		}
113→		return nil
114→	}
115→
116→	// Get the current strategy for condense operations
117→	strat := GetStrategy(ctx)
118→
119→	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
120→
121→	for _, ss := range stuck {
122→		displayStuckSession(cmd, ss)
123→
124→		if force {
125→			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
126→				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
127→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
128→				} else {
129→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
130→				}
131→			} else {
132→				// Discard if we can't condense
133→				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
134→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
135→				} else {
136→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
137→				}
138→			}
139→			continue
140→		}
141→
142→		// Interactive: prompt for action
143→		action, err := promptSessionAction(ss)
144→		if err != nil {
145→			if errors.Is(err, huh.ErrUserAborted) {
146→				return nil
147→			}
148→			return fmt.Errorf("failed to get action: %w", err)
149→		}
150→
151→		switch action {
152→		case "condense":
153→			if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
154→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
155→			} else {
156→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
157→			}
158→		case "discard":
159→			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
160→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
161→			} else {
162→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
163→			}
164→		case "skip":
165→			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
166→		}
167→	}
168→
169→	if metadataErr != nil {
170→		return fmt.Errorf("metadata check failed: %w", metadataErr)
171→	}
172→
173→	return nil
174→}
