229→// displayStuckSession prints diagnostic info for a stuck session.
230→func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
231→	w := cmd.OutOrStdout()
232→
233→	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
234→	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
235→	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
236→
237→	if ss.State.AgentType != "" {
238→		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
239→	}
240→
241→	if ss.State.LastInteractionTime != nil {
242→		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
243→	}
244→
245→	shadowStatus := "not found"
246→	if ss.HasShadowBranch {
247→		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
248→	}
249→	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
250→	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
251→}
