253→// promptSessionAction asks the user what to do with a stuck session.
254→func promptSessionAction(ss stuckSession) (string, error) {
255→	var action string
256→
257→	options := make([]huh.Option[string], 0, 3)
258→	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
259→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
260→	}
261→	options = append(options,
262→		huh.NewOption("Discard (remove session data)", "discard"),
263→		huh.NewOption("Skip (leave as-is)", "skip"),
264→	)
265→
266→	form := NewAccessibleForm(
267→		huh.NewGroup(
268→			huh.NewSelect[string]().
269→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
270→				Options(options...).
271→				Value(&action),
272→		),
273→	)
274→
275→	if err := form.Run(); err != nil {
276→		return "", fmt.Errorf("session fix prompt failed: %w", err)
277→	}
278→
279→	return action, nil
280→}
