282→// discardSession removes session state and cleans up the shadow branch.
283→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
284→	// Clear session state file
285→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
286→		return fmt.Errorf("failed to clear session state: %w", err)
287→	}
288→
289→	// Delete shadow branch if it exists and no other sessions need it
290→	if ss.HasShadowBranch {
291→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
292→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
293→		} else if shouldDelete {
294→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
295→				// Branch already gone is not an error — keeps discard idempotent
296→				if !errors.Is(err, strategy.ErrBranchNotFound) {
297→					return fmt.Errorf("failed to delete shadow branch: %w", err)
298→				}
299→			}
300→		}
301→	}
302→
303→	return nil
304→}
