306→// checkDisconnectedMetadata detects and optionally repairs disconnected
307→// local/remote metadata branches (the "empty-orphan bug").
308→func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
309→	repo, err := openRepository(cmd.Context())
310→	if err != nil {
311→		return fmt.Errorf("failed to open repository: %w", err)
312→	}
313→
314→	ctx := cmd.Context()
315→	disconnected, err := strategy.IsMetadataDisconnected(ctx, repo)
316→	if err != nil {
317→		return fmt.Errorf("could not check metadata branch state: %w", err)
318→	}
319→
320→	w := cmd.OutOrStdout()
321→
322→	if !disconnected {
323→		fmt.Fprintln(w, "Metadata branches: OK")
324→		return nil
325→	}
326→
327→	fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
328→	fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
329→	fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
330→	fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
331→
332→	if !force {
333→		var confirmed bool
334→		form := NewAccessibleForm(
335→			huh.NewGroup(
336→				huh.NewConfirm().
337→					Title("Fix disconnected metadata branches?").
338→					Value(&confirmed),
339→			),
340→		)
341→		if formErr := form.Run(); formErr != nil {
342→			if errors.Is(formErr, huh.ErrUserAborted) {
343→				return nil
344→			}
345→			return fmt.Errorf("prompt failed: %w", formErr)
346→		}
347→		if !confirmed {
348→			fmt.Fprintln(w, "  -> Skipped")
349→			return nil
350→		}
351→	}
352→
353→	if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, cmd.ErrOrStderr()); fixErr != nil {
354→		return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
355→	}
356→
357→	fmt.Fprintln(w, "  -> Fixed: metadata branches reconciled")
358→	return nil
359→}
