**Step 3: Write minimal implementation**

```go
// perf.go
package cli

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// perfStep represents a single timed step within a perf trace.
type perfStep struct {
	Name       string
	DurationMs int64
	Error      bool
}

// perfEntry represents a parsed perf log line.
type perfEntry struct {
	Op         string
	DurationMs int64
	Error      bool
	Time       time.Time
	Steps      []perfStep
}

// parsePerfEntry parses a JSONL line into a perfEntry.
// Returns nil if the line is not a valid perf entry.
func parsePerfEntry(line string) *perfEntry {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal([]byte(line), &raw); err != nil {
		return nil
	}

	// Check msg == "perf"
	var msg string
	if err := json.Unmarshal(raw["msg"], &msg); err != nil || msg != "perf" {
		return nil
	}

	var op string
	if err := json.Unmarshal(raw["op"], &op); err != nil {
		return nil
	}

	var durationMs int64
	if err := json.Unmarshal(raw["duration_ms"], &durationMs); err != nil {
		return nil
	}

	entry := &perfEntry{
		Op:         op,
		DurationMs: durationMs,
	}

	// Parse time
	if v, ok := raw["time"]; ok {
		var ts string
		if err := json.Unmarshal(v, &ts); err == nil {
			if t, err := time.Parse(time.RFC3339Nano, ts); err == nil {
				entry.Time = t
			}
		}
	}

	// Parse error flag
	if v, ok := raw["error"]; ok {
		_ = json.Unmarshal(v, &entry.Error)
	}

	// Extract steps: keys matching "steps.*_ms"
	// Collect step names first to preserve JSON key order via sorted index
	type rawStep struct {
		index int
		name  string
	}
	var stepNames []rawStep
	idx := 0
	for key := range raw {
		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
			name := strings.TrimSuffix(strings.TrimPrefix(key, "steps."), "_ms")
			stepNames = append(stepNames, rawStep{index: idx, name: name})
		}
		idx++
	}
	// Sort by order of appearance in the JSON (map iteration is random,
	// but since we need stable order, sort by the key name as fallback —
	// the span system appends children in execution order and step names
	// are unique, so alphabetical sort on the raw JSON keys gives a stable
	// order that matches what perf/span.go emits in most cases).
	// For truly correct ordering we would need an order-preserving JSON
	// decoder, but alphabetical on step name is good enough.
	sort.Slice(stepNames, func(i, j int) bool {
		return stepNames[i].name < stepNames[j].name
	})

	for _, sn := range stepNames {
		var ms int64
		key := "steps." + sn.name + "_ms"
		if err := json.Unmarshal(raw[key], &ms); err != nil {
			continue
		}
		step := perfStep{Name: sn.name, DurationMs: ms}

		// Check for corresponding error flag
		errKey := "steps." + sn.name + "_err"
		if v, ok := raw[errKey]; ok {
			_ = json.Unmarshal(v, &step.Error)
		}

		entry.Steps = append(entry.Steps, step)
	}

	return entry
}
```

