import (
	"fmt"
	"io"
)

// renderPerfEntries writes formatted perf tables to w.
func renderPerfEntries(w io.Writer, entries []perfEntry) {
	if len(entries) == 0 {
		fmt.Fprintln(w, "No perf entries found.")
		fmt.Fprintln(w, "Perf traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set")
		fmt.Fprintln(w, "in your shell profile, or set log_level to \"DEBUG\" in .entire/settings.json.")
		return
	}

	for i, entry := range entries {
		if i > 0 {
			fmt.Fprintln(w)
		}

		// Header: op  totalms  timestamp
		ts := ""
		if !entry.Time.IsZero() {
			ts = "  " + entry.Time.Format(time.RFC3339)
		}
		fmt.Fprintf(w, "%s  %dms%s\n", entry.Op, entry.DurationMs, ts)

		if len(entry.Steps) == 0 {
			continue
		}

		// Compute column widths
		maxNameLen := len("STEP")
		for _, s := range entry.Steps {
			if len(s.Name) > maxNameLen {
				maxNameLen = len(s.Name)
			}
		}

		fmt.Fprintln(w)
		fmt.Fprintf(w, "  %-*s  %s\n", maxNameLen, "STEP", "DURATION")

		for _, s := range entry.Steps {
			durStr := fmt.Sprintf("%dms", s.DurationMs)
			errMark := ""
			if s.Error {
				errMark = "  x"
			}
			fmt.Fprintf(w, "  %-*s  %8s%s\n", maxNameLen, s.Name, durStr, errMark)
		}
	}
}
