162→// renderPerfEntries writes a formatted table of perf entries to w.
163→// If entries is empty, it prints a help message about enabling perf traces.
164→func renderPerfEntries(w io.Writer, entries []perfEntry) {
165→	if len(entries) == 0 {
166→		fmt.Fprintln(w, "No perf entries found.")
167→		fmt.Fprintln(w, `Perf traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
168→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
169→		return
170→	}
171→
172→	for i, entry := range entries {
173→		if i > 0 {
174→			fmt.Fprintln(w)
175→		}
176→
177→		// Header line: op  duration  [timestamp]
178→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
179→		if !entry.Time.IsZero() {
180→			header += "  " + entry.Time.Format(time.RFC3339)
181→		}
182→		fmt.Fprintln(w, header)
183→		fmt.Fprintln(w)
184→
185→		if len(entry.Steps) == 0 {
186→			continue
187→		}
188→
189→		// Compute max step name width (at least len("STEP"))
190→		nameWidth := len("STEP")
191→		for _, s := range entry.Steps {
192→			if len(s.Name) > nameWidth {
193→				nameWidth = len(s.Name)
194→			}
195→		}
196→
197→		// Column header
198→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
199→
200→		// Step rows
201→		for _, s := range entry.Steps {
202→			dur := fmt.Sprintf("%dms", s.DurationMs)
203→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
204→			if s.Error {
205→				line += "  x"
206→			}
207→			fmt.Fprintln(w, line)
208→		}
209→	}
210→}
